const allowed = new Set(["internal_task","public_content","first_pr_pitch","creator_outreach","lifecycle_send","paid_budget_change","commercial_agreement","member_removal","canonical_blueprint_change"]);
function parse(role, response) {
  if (response.error || response.status !== 'completed') return { role, status: 'failed', proposals: [] };
  const text = response.output?.flatMap(o => o.content ?? []).find(c => c.type === 'output_text')?.text;
  try {
    const value = JSON.parse(text);
    if (typeof value.summary !== 'string' || !Array.isArray(value.evidence) || !Array.isArray(value.missing_inputs) ||
        !Array.isArray(value.proposals) || value.proposals.some(p => !allowed.has(p.type) ||
          typeof p.title !== 'string' || typeof p.draft !== 'string')) throw new Error('Invalid report');
    return { role, status: 'completed', summary: value.summary, evidence: value.evidence,
      missingInputs: value.missing_inputs, proposals: value.proposals.filter(proposal => proposal.type === 'internal_task').slice(0, 2)
        .map(p => ({ ...p, status: 'pending_review', agent: role })) };
  } catch {
    return { role, status: 'invalid_response', proposals: [] };
